odoo.define('generic_request_field.fields_widget', function (require) {
    "use strict";

    var core = require('web.core');
    var field_registry = require('web.field_registry');
    var DebouncedField = require('web.basic_fields').DebouncedField;

    var qweb = core.qweb;


    var FieldRequestFields = DebouncedField.extend({
        tagName: 'div',
        className: 'o_request_fields',
        resetOnAnyFieldChange: true,
        supportedFieldTypes: ['text'],

        custom_events: _.extend({}, DebouncedField.prototype.custom_events, {
            field_changed: '_onFieldChanged',
        }),
        events: _.extend({}, DebouncedField.prototype.events, {
            'change .request_field_value': '_onRequestFieldChanged',
        }),

        init: function () {
            this._super.apply(this, arguments);

            this.isReadonly = this.mode === 'readonly';

            this.isDirty = false;
            this.lastChangeEvent = null;

            this.o_value = this._parseFieldsValue(this.value);
        },

        _reset: function () {
            this._super.apply(this, arguments);
            this.o_value = this._parseFieldsValue(this.value);
        },

        reset: function (record, event) {
            this._reset(record, event);
            if (!event || event === this.lastChangeEvent) {
                this.isDirty = false;
            }
            if (this.isDirty) {
                return $.when();
            }

            // If current field is changed (target of event) and
            // there is no difference between changed value and
            // current value (after reset), then we do not need to re-render
            // the field.
            // Also, take attention, that here we compare two json
            // representations of the field (one from event, other current
            // value of the field). Comparing as json objects to avoid
            // issues with different representations of same json in strings
            if (event && event.target === this &&
                    _.isEqual(
                        this._parseFieldsValue(event.data.changes[this.name]),
                        this.o_value)) {
                return $.when();
            }
            // Other wise, completely re-render this field
            // For example, in case when request type was changed
            return this._render();
        },

        _getValue: function () {
            return this._formatFieldsValue(this.o_value);
        },

        /* Convert string representation of value to objects */
        _parseFieldsValue: function (value) {
            return JSON.parse(value);
        },

        /* Convert object value to string representation */
        _formatFieldsValue: function (value) {
            if (value) {
                return JSON.stringify(value);
            }
            return '';
        },

        _getTemplateContext: function () {
            return {
                value: this.o_value,
                attrs: this.attrs,
                options: this.nodeOptions,
            };
        },

        _renderEdit: function () {
            var self = this;
            self.$el.html(
                qweb.render(
                    'RequestFields.widget.edit',
                    self._getTemplateContext()));
        },

        _renderReadonly: function () {
            var self = this;
            self.$el.html(
                qweb.render(
                    'RequestFields.widget.readonly',
                    self._getTemplateContext()));
        },

        /* When request field (one of that are generated by this widget)
         * changed
         */
        _onRequestFieldChanged: function (ev) {
            var $field_input = $(ev.target);
            var field_id = $field_input.data('field_id');
            this.o_value.fields_info[field_id].value = $field_input.val();
            this._doAction();
        },

        _onFieldChanged: function (event) {
            this.lastChangeEvent = event;
        },
    });

    field_registry.add('request_fields', FieldRequestFields);
    return FieldRequestFields;
});
